(function(root){
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>Number(n||0).toFixed(2), modes=['ideal','custom','random'];
function prepare(config,results,journal=[],meta={}){const c=JSON.parse(JSON.stringify(config));if(c.background)c.background='[Uploaded image omitted from report; see saved project]';const runs={};for(const mode of modes){const r=results?.[mode];if(!r)continue;const times=new Map();for(const row of r.rows){if(!times.has(row.time_s))times.set(row.time_s,{time_s:row.time_s,active:0,queued:0,waiting:0,completed:0,density:0});let t=times.get(row.time_s);t.active+=row.active;t.queued+=row.queued;t.waiting+=row.waiting_entry||0;t.completed+=row.completed;t.density=Math.max(t.density,row.peak_local_density_p_m2)}let heat=new Map();for(const frame of r.frames)for(const cell of root.EHDensity.build(frame,c.scale)){if(!heat.has(cell.key)||heat.get(cell.key).density<cell.density)heat.set(cell.key,cell)}runs[mode]={total:r.total,completed:r.completed,active:r.active??0,waiting:r.waiting??0,events:r.events,barriers:r.barriers||[],audit:r.audit||{violations:[]},timeline:[...times.values()],heat:[...heat.values()],finalRows:r.rows.filter(x=>x.time_s===c.duration).map(row=>({...row,admitted_total:r.rows.filter(x=>x.route_id===row.route_id).reduce((n,x)=>n+x.spawned,0)}))}}const warnings=[];for(const e of c.events){if(e.type==='surge'&&/collaps/i.test(e.name))warnings.push(`“${e.name}” is a Surge (+${e.people} arrivals), not a collapse. Its saved type was preserved.`)}if(!journal.length||journal.some(e=>e.action==='project_opened'&&e.details?.historicalJournalAvailable===false))warnings.push('This scene contains no historical decision journal. Earlier clicks and reasons cannot be reconstructed. This report records the imported configuration as the baseline.');return{version:3,generatedAt:new Date().toISOString(),config:c,runs,journal,meta,warnings}}
const styles=`*{box-sizing:border-box}body{font:14px/1.6 Arial,sans-serif;color:#273126;background:#f3f3ed;margin:0}main{max-width:1160px;margin:auto;padding:50px 44px}header{border-bottom:2px solid #273126;padding-bottom:28px}h1{font-size:44px;line-height:1.05;font-weight:500;letter-spacing:-2px;margin:14px 0}h2{font-size:24px;font-weight:500;margin-top:38px}h3{font-size:16px;margin-top:28px}small,.muted{color:#6c7864}.eyebrow{font:11px monospace;letter-spacing:2px;color:#6d7e5c}.callout{background:#e4ebda;padding:16px 20px;border-left:4px solid #647d44;margin:20px 0}.warning{background:#f9e6cd;border-color:#d38837}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:26px 0}.stat{padding:18px;background:#e3e8da}.stat strong{display:block;font-size:28px;font-weight:400}.stat small{font:10px monospace;letter-spacing:1px}table{width:100%;border-collapse:collapse;font-size:12px;margin:15px 0;overflow-wrap:anywhere}td,th{padding:10px 9px;text-align:left;border-bottom:1px solid #cdd6c3;vertical-align:top}th{font-weight:600;background:#e6ebdf}svg{width:100%;height:auto;border:1px solid #cdd6c3;background:#e9eddf}.plots{display:grid;grid-template-columns:1fr 1fr;gap:20px}.legend{display:flex;gap:13px;font:10px monospace;margin:12px 0;flex-wrap:wrap}.legend b{display:inline-block;width:12px;height:12px;vertical-align:middle;margin-right:4px}pre{white-space:pre-wrap;word-break:break-word;font:11px/1.5 monospace;background:#e7ebdf;padding:12px}details{border-bottom:1px solid #cdd6c3;padding:12px 0}summary{cursor:pointer;font-size:12px}button{padding:10px 16px;border:0;background:#273126;color:#d6fa63;cursor:pointer;float:right}.foot{margin-top:42px;border-top:2px solid #273126;padding-top:18px;font-size:11px}@media(max-width:700px){main{padding:25px 16px}.grid{grid-template-columns:1fr 1fr}.plots{grid-template-columns:1fr}h1{font-size:32px}table{font-size:10px}td,th{padding:7px 4px}}@media print{body{background:white}main{padding:0;max-width:none}button{display:none}h2,h3{break-after:avoid}tr,svg,.stat{break-inside:avoid}.plots{display:block}.plots>div{margin-bottom:20px}details{break-inside:avoid}}`;
function table(headers,rows){return'<table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function mapSvg(data,heat=[]){const c=data.config;let s='<svg viewBox="0 0 1000 720" role="img" aria-label="Recorded route geometry and density"><rect width="1000" height="700" fill="#e3e9d9"/>';if(c.useOriginalVenue!==false&&root.EHVenue)for(const a of root.EHVenue.venue.areas)s+=`<rect x="${a.x}" y="${a.y}" width="${a.w}" height="${a.d}" fill="${a.color}" stroke="#a0ad91"/>`;for(const h of heat)s+=`<rect x="${h.x}" y="${h.y}" width="${h.w}" height="${h.h}" fill="${h.color}" opacity=".85"><title>${num(h.density)} people/m² maximum</title></rect>`;for(const [i,r]of c.routes.entries()){s+=`<polyline points="${r.points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${/^#[a-f\d]{6}$/i.test(r.color)?r.color:'#333333'}" stroke-width="3"/><text x="${r.points[0].x+8}" y="${Math.max(14,r.points[0].y-8)}" font-family="Arial" font-size="13" fill="#273126">${esc(r.name)}</text>`}for(const e of c.events){const r=c.routes.find(r=>r.id===e.routeId);if(!r)continue;let cum=[0];for(let i=1;i<r.points.length;i++)cum.push(cum.at(-1)+Math.hypot(r.points[i].x-r.points[i-1].x,r.points[i].y-r.points[i-1].y));let at=e.at*cum.at(-1),i=1;while(i<cum.length-1&&at>cum[i])i++;let f=(at-cum[i-1])/(cum[i]-cum[i-1]||1),x=r.points[i-1].x+(r.points[i].x-r.points[i-1].x)*f,y=r.points[i-1].y+(r.points[i].y-r.points[i-1].y)*f;s+=`<circle cx="${x}" cy="${y}" r="${e.type==='collapse'?(e.radiusM??3)/c.scale:9}" fill="none" stroke="#ae3825" stroke-width="2"/><text x="${x+12}" y="${y-10}" font-family="Arial" font-size="12">${esc(e.name+' ['+e.type+']')}</text>`}return s+'</svg>'}
function chart(run,duration){const series=run.timeline,max=Math.max(1,...series.map(r=>r.queued+r.waiting));let s='<svg viewBox="0 0 1000 220" role="img" aria-label="Queue and outside waiting over simulation time"><path d="M55 15V180H970" fill="none" stroke="#93a281"/>';for(const[key,col]of[['queued','#d26136'],['waiting','#5c7e41']])s+=`<polyline points="${series.map(r=>(55+r.time_s/duration*915)+','+(180-r[key]/max*155)).join(' ')}" fill="none" stroke="${col}" stroke-width="3"/>`;s+=`<text x="15" y="30" font-size="12">${max}</text><text x="45" y="205" font-size="12">0 s</text><text x="900" y="205" font-size="12">${duration} s</text></svg>`;return s}
function body(d){let c=d.config,base=c.routes.reduce((n,r)=>n+r.count,0),routes=c.routes,history=d.journal||[];let html=`<main><header><button onclick="window.print()">Print / Save PDF</button><div class="eyebrow">EVENT HORIZON / MASTER RECORD / V3</div><h1>The scene. The decisions.<br>The resulting movement.</h1><p>Generated ${esc(d.generatedAt)} · ${esc(d.meta.source||'Current studio project')}<br><small>Source SHA-256: ${esc(d.meta.sourceSha256||'Not supplied')} · Engine: kinematic-v3</small></p></header><div class="grid"><div class="stat"><small>ROUTES</small><strong>${routes.length}</strong></div><div class="stat"><small>BASE POPULATION</small><strong>${base}</strong></div><div class="stat"><small>DURATION</small><strong>${c.duration}s</strong></div><div class="stat"><small>LOGGED DECISIONS</small><strong>${history.length}</strong></div></div><div class="callout">This is a simulation experiment record. Results below are model outputs, not validated crowd-risk forecasts. ${esc(d.meta.provenance||'Runs are generated from the configuration recorded here.')}</div>`;
for(const w of d.warnings||[])html+='<div class="callout warning">'+esc(w)+'</div>';
html+='<h2>1 / Project and workflow</h2><p>Event Horizon models a venue, generates ideal, manual-incident and random-collapse crowd scenarios, then exports movement features for comparison with observed crowd trajectories. The current studio covers scene authoring, synthetic simulation, playback and exports. Live CCTV matching, calibrated forecasts and operational alerts remain separate future components.</p><p><b>Workflow:</b> venue & scale → user-drawn routes → population & incident decisions → three seeded runs → movement features, heatmaps and audits → future held-out prediction evaluation.</p>';
html+='<h2>2 / Venue and route decisions</h2>'+table(['Setting','Recorded value'],[['Venue',c.useOriginalVenue===false?'Uploaded reference / custom scene':'Original sketch-based schematic'],['Scale',c.scale+' m/map unit'],['Canvas',1000*c.scale+' × '+700*c.scale+' m (assumed until calibrated)'],['Duration',c.duration+' s'],['Seed',c.seed],['Random collapses',c.randomCount]])+table(['Route','Population','Nominal speed','Width','Points','Length · m'],routes.map(r=>{let len=0;for(let i=1;i<r.points.length;i++)len+=Math.hypot(r.points[i].x-r.points[i-1].x,r.points[i].y-r.points[i-1].y)*c.scale;return[r.name,r.count,r.speed+' m/s',r.width+' m',r.points.length,num(len)]}))+mapSvg(d);
html+='<h2>3 / Manual incidents</h2>'+table(['Name','Actual type','Timing','Route','Position','Additional people','Radius'],c.events.map(e=>[e.name,e.type,e.start+'–'+e.end+' s',routes.find(r=>r.id===e.routeId)?.name,num(e.at*100)+'%',e.type==='surge'?e.people:0,e.type==='collapse'?(e.radiusM??3)+' m':'—']))+'<p>Closure intervals are [start, end): a closure at 150–300 is active from 150 up to 300. Frames are timestamp snapshots; movement from t to t+1 uses the closure state at t. The final frame does not advance another step. A spatial collapse blocks every intersecting path, including repeated visits to the same location. Arrivals whose source is inside an active block wait outside admission; people already beyond its footprint may continue.</p>';
html+='<h2>4 / Run comparison</h2>';let summary=[];for(const mode of modes){const r=d.runs[mode];if(!r)continue;summary.push([mode,r.total,r.completed,r.active,r.waiting,Math.max(0,...r.timeline.map(x=>x.queued)),num(Math.max(0,...r.timeline.map(x=>x.density))),r.audit.violations?.length||0])}html+=summary.length?table(['Run','Scheduled','Completed','Active at end','Waiting outside at end','Peak total queued','Peak cell p/m²','Barrier violations'],summary):'<p>No runs available. Render to include results.</p>';
for(const mode of modes){const r=d.runs[mode];if(!r)continue;html+=`<h3>${esc(mode.toUpperCase())}</h3><div class="plots"><div>${mapSvg(d,r.heat)}<small>Maximum density per occupied 2 m cell across the whole run; maxima are not simultaneous.</small></div><div>${chart(r,c.duration)}<div class="legend"><span><b style="background:#d26136"></b>Queued inside</span><span><b style="background:#5c7e41"></b>Waiting outside admission</span></div></div></div><div class="legend">Density · people/m² ${[[.5,'0–1'],[1.5,'1–2'],[3,'2–4'],[5,'4–6'],[6,'6+']].map(([n,label])=>'<span><b style="background:'+root.EHDensity.color(n)+'"></b>'+label+'</span>').join('')}</div>`;html+=table(['Route','Admitted','Completed','Active at end','Waiting at end'],r.finalRows.map(row=>[row.route_name,row.admitted_total??'Not recorded',row.completed,row.active,row.waiting_entry||0]));html+=`<p>Blocked movement attempts: ${r.audit.preventedMoves||0} agent-steps. Audited forbidden crossings: ${r.audit.violations?.length||0}. Waiting people remain part of the scheduled population; they are not counted as people inside the venue.</p>`;if(r.barriers.length)html+=table(['Closure','Timing','Radius','Intersecting routes'],r.barriers.map(b=>[b.name,b.start+'–'+b.end+' s',b.radiusM+' m',b.routes.map(x=>routes[x.ri]?.name).join(', ')]));if(mode==='random')html+=table(['Generated incident','Route','Timing','Position'],r.events.map(e=>[e.name,routes.find(x=>x.id===e.routeId)?.name,e.start+'–'+e.end+' s',num(e.at*100)+'%']))}
html+='<h2>5 / Decision journal</h2><p>The journal records actions and configuration changes from this version onward, with timestamps, before/after differences, and optional notes. Imported older scenes establish a baseline; their missing history is not invented. Camera and heatmap choices are logged as display decisions, separate from simulation inputs.</p>';
for(const [i,e]of history.entries())html+=`<details open><summary>${i+1}. ${esc(e.timestamp)} · ${esc(e.action)}</summary><pre>${esc(JSON.stringify({details:e.details,changes:e.changes},null,2))}</pre></details>`;if(!history.length)html+='<p>No historical decisions were supplied.</p>';
html+='<h2>6 / Outputs and interpretation</h2><p>01_ideal_flow.csv excludes imposed incidents. 02_custom_disasters.csv includes your manual events. 03_random_collapses.csv uses the same base population with seeded random collapses. Columns include scheduled arrivals, admitted/spawned counts, completed exits, active people, waiting_entry, speed, mean route density, peak local density, queued and blocked attempts. All three use the same one-second grid. Run manifests and incident schedules are scenario truth and must not be predictor inputs.</p><h2>7 / Model assumptions and limits</h2><p>The 3D view visualizes a ground-plane kinematic model. Routes are centerlines with single-file spacing; stated width affects the density estimate, not multiple walking lanes. Visual buildings and ponds are not automatic collision geometry. Speeds and arrivals are assumed; falls, injuries, contact forces, crowd pressure and panic are not modeled. The heatmap uses occupied 2 m cells and a fixed 0–6+ people/m² color scale; it is not a validated safety classification. Seed consistency supports comparison, not real-world validation.</p><p>Before deployment, measure the venue, verify gate positions and capacities, calibrate movement against CCTV trajectories, separate training and held-out scenarios, and evaluate forecast lead time and false-alert rates. This report contains no invented field validation.</p><h2>8 / Reproducibility record</h2><details><summary>Full configuration (image bytes excluded)</summary><pre>'+esc(JSON.stringify(c,null,2))+'</pre></details><div class="foot">Created with OpenAI Codex assistance. User-supplied venue and scene; all movement data synthetic. Frontend WebGL visual QA remains a separate hardware/browser check.</div></main>';return html}
function build(d){return'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event Horizon — Master Report</title><style>'+styles+'</style></head><body>'+body(d)+'</body></html>'}
const api={prepare,body,build,styles};root.EHReport=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
